const root=document.getElementById('app');
const navItems=[['control','Control Center','CC'],['overview','System overview','overview'],['live','Live Monitoring','◉'],['analysis','Video Analysis','▣'],['incidents','Incidents','incidents'],['modules','AI Modules','◇'],['settings','Settings','⚙']];
let me=null,page='control',cams=[],allIncidents=[],timezone='Asia/Bangkok',pageTimer=null,analysisObserver=null,selectedJob=null,loadedResult=null,jobFilter='All',controlCenterInstance=null,liveViewerInstance=null,selectedCameraId=null;
const esc=value=>String(value??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
function message(value){return typeof value==='string'?value:JSON.stringify(value)}
async function api(path,options={}){const response=await fetch('/api'+path,{credentials:'same-origin',...options,headers:{...(options.body&&typeof options.body==='string'?{'Content-Type':'application/json'}:{}),...(options.headers||{})}});if(response.status===401&&me&&!['/auth/login','/auth/session'].includes(path)){controlCenterInstance?.dispose();controlCenterInstance=null;me=null;login('Your session expired. Sign in again.');throw Error('Your session expired. Sign in again.')}if(!response.ok){let body={};try{body=await response.json()}catch{}throw Error(message(body.detail)||`Request failed (${response.status})`)}if(response.status===204)return null;return response.json()}
function stopTimers(){analysisObserver?.disconnect();analysisObserver=null;if(pageTimer){clearInterval(pageTimer);pageTimer=null}}
// ---- Feature registry (docs/features/navigation-registry.md) ----
// Feature files register before app.js runs, so adding a page or session service never edits this shell:
//   window.VisorPages.push({id, label, icon, after, mount({api, me, host, onNavigate, formatTime}) -> {dispose()}})
//   window.VisorServices.push({id, start({api, me, onNavigate}) -> {attach(topbarSlot), stop()}})
let featureInstance=null,sessionServices=[],ccFocus=null;
const featurePages=()=>window.VisorPages||[];
function shellNav(){const items=[...navItems];for(const p of featurePages()){if(items.some(([id])=>id===p.id))continue;const at=items.findIndex(([id])=>id===p.after);items.splice(at>=0?at+1:items.length,0,[p.id,p.label,p.icon||'•'])}return items}
// navigateTo('live',{cameraId}) opens that camera's settings and rules; navigateTo('control',{focus:{incidentId}}) selects an incident.
function navigateTo(target,options={}){if(page==='control'&&controlCenterInstance&&!controlCenterInstance.confirmLeave())return;page=target;ccFocus=options.focus||null;selectedJob=null;loadedResult=null;render();if(target==='live'&&options.cameraId)cameraDetail(options.cameraId)}
function stopServices(){for(const s of sessionServices){try{s.stop?.()}catch(error){console.error('service_stop_failed',error)}}sessionServices=[]}
function attachServices(){const slot=document.getElementById('topbarSlot');for(const s of sessionServices)s.attach?.(slot)}
function startServices(){stopServices();for(const s of window.VisorServices||[]){try{const instance=s.start({api,me,onNavigate:navigateTo});if(instance)sessionServices.push(instance)}catch(error){console.error('service_start_failed',s.id,error)}}attachServices()}
async function init(){window.VisorMonitoring.setUnauthorizedHandler(()=>{if(me){me=null;login()}});try{const session=await api('/auth/session');if(!session.authenticated){login();return}me=session;await loadBase();render();startServices()}catch{login()}}
function login(reason=''){
 featureInstance?.dispose();featureInstance=null;stopServices();selectedCameraId=null;liveViewerInstance?.dispose();liveViewerInstance=null;window.VisorMonitoring.clearSession();controlCenterInstance?.dispose();controlCenterInstance=null;stopTimers();document.querySelectorAll('dialog').forEach(d=>d.close());
 root.innerHTML=`<main class="login-wrap"><section class="login-card"><div class="brand"><span class="brand-mark" aria-hidden="true">V</span><span>Visor<small>BY VIGILON</small></span></div><h1>Sign in to your workspace</h1><p class="muted">Monitor your cameras. Review what matters.</p><form id="loginForm"><label class="field">Username<input name="username" autocomplete="username" required autofocus></label><label class="field">Password<span class="password-wrap"><input id="loginPassword" name="password" type="password" autocomplete="current-password" required><button class="ghost small" type="button" id="showPassword" aria-controls="loginPassword" aria-pressed="false">Show</button></span></label><p id="loginError" class="error" role="alert">${esc(reason)}</p><button type="submit">Sign in</button></form><p class="login-footer">Your configured cameras and incident history.<br>Access is limited to authorized operators.</p></section></main>`;
 document.getElementById('showPassword').onclick=event=>{const input=document.getElementById('loginPassword'),visible=input.type==='password';input.type=visible?'text':'password';event.currentTarget.textContent=visible?'Hide':'Show';event.currentTarget.setAttribute('aria-pressed',String(visible))};
 document.getElementById('loginForm').onsubmit=async event=>{event.preventDefault();const form=event.currentTarget,button=form.querySelector('[type=submit]'),out=document.getElementById('loginError');if(button.disabled)return;button.disabled=true;button.textContent='Signing in…';out.textContent='';try{me=await api('/auth/login',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(form)))});await loadBase();page='control';render();startServices()}catch(error){out.textContent=error.message;button.disabled=false;button.textContent='Sign in'}};
}
async function loadBase(){[cams,allIncidents]=await Promise.all([api('/cameras'),api('/incidents?limit=100')]);try{timezone=(await api('/settings/public')).display_timezone||timezone}catch{}}
function dateLabel(value){if(!value)return'—';try{return new Intl.DateTimeFormat(undefined,{dateStyle:'medium',timeStyle:'medium',timeZone:timezone}).format(new Date(value))}catch{return value}}
function pill(label,tone=''){return `<span class="status ${tone}">${esc(label)}</span>`}
function stateTone(state){if(['ONLINE','READY','RUNNING','COMPLETED','ACKNOWLEDGED','RESOLVED'].includes(state))return'good';if(['QUEUED','CONNECTING','LOADING','RELOAD_QUEUED','CANCELLING'].includes(state))return'warn';if(['OFFLINE','FAILED','ERROR','MISSING_WEIGHTS','INVALID_CONFIG','UNSUPPORTED_MODEL','DEPENDENCY_MISSING','NEW'].includes(state))return'bad';return''}
function pageHead(title,subtitle,actions=''){return `<header class="page-head"><div class="page-title-wrap"><div class="eyebrow">Operations</div><h1>${esc(title)}</h1><p class="muted">${esc(subtitle)}</p></div>${actions?`<div class="actions-row">${actions}</div>`:''}</header>`}
function render(){
 document.body.style.overflow='';
 featureInstance?.dispose();featureInstance=null;liveViewerInstance?.dispose();liveViewerInstance=null;controlCenterInstance?.dispose();controlCenterInstance=null;stopTimers();
 const groups=[['Operations',['control','live','incidents']],['Analysis',['analysis','modules']],['Configuration',['overview','settings']]],items=shellNav();
 const nav=items.map(([id,label])=>`<button class="nav-link ${page===id?'active':''}" data-page="${esc(id)}" aria-current="${page===id?'page':'false'}"><span class="nav-icon">${window.VisorUI.icon(id)}</span><span>${esc(label)}</span></button>`);
 const navigation=groups.map(([label,ids])=>`<div class="nav-label">${label}</div><div class="nav-list">${items.map(([id],index)=>ids.includes(id)?nav[index]:'').join('')}</div>`).join('');
 const extras=items.map(([id],index)=>groups.some(([,ids])=>ids.includes(id))?'':nav[index]).join('');
 root.innerHTML=`<a href="#content" class="skip-link">Skip to content</a><div class="shell"><button class="nav-backdrop" tabindex="-1" aria-label="Close navigation"></button><aside class="sidebar" id="primarySidebar"><div class="brand"><span class="brand-mark" aria-hidden="true">V</span><span>Visor<small>BY VIGILON</small></span></div><button class="ghost small nav-close" aria-label="Close navigation">Close</button><nav aria-label="Primary navigation">${navigation}${extras?`<div class="nav-label">More tools</div><div class="nav-list">${extras}</div>`:''}</nav><div class="sidebar-foot"><div class="user-chip"><div class="account-summary"><span class="account-avatar" aria-hidden="true">${esc(me.username.slice(0,1).toUpperCase())}</span><div><div class="user-name">${esc(me.username)}</div><div class="muted small-text">${esc(me.role==='ADMIN'?'Administrator':'Operator')}</div></div></div><button id="logout" class="ghost small">Sign out</button></div></div></aside><div class="main-area"><header class="topbar"><button class="secondary menu-toggle" aria-label="Open navigation" aria-expanded="false" aria-controls="primarySidebar">${window.VisorUI.icon('menu')} Menu</button><span class="topbar-label">Camera operations</span><div id="topbarSlot" class="topbar-slot"></div><div class="topbar-meta"><span>${esc(timezone)}</span><span>${esc(me.role==='ADMIN'?'Administrator':'Operator')}</span></div></header><main id="content" class="content" tabindex="-1"></main></div></div>`;
 const sidebar=document.getElementById('primarySidebar'),toggle=document.querySelector('.menu-toggle'),backdrop=document.querySelector('.nav-backdrop'),mobile=window.matchMedia('(max-width:900px)');
 const setMenu=open=>{document.body.style.overflow=mobile.matches&&open?'hidden':'';if(mobile.matches&&open){sidebar.setAttribute('role','dialog');sidebar.setAttribute('aria-modal','true');sidebar.setAttribute('aria-label','Navigation')}else{sidebar.removeAttribute('role');sidebar.removeAttribute('aria-modal')}sidebar.classList.toggle('open',open);backdrop.classList.toggle('open',open);toggle.setAttribute('aria-expanded',String(open));sidebar.inert=mobile.matches&&!open;document.querySelector('.main-area').inert=mobile.matches&&open;if(open)sidebar.querySelector('.nav-link.active')?.focus();else toggle.focus()};
 sidebar.inert=mobile.matches;
 toggle.onclick=()=>setMenu(true);sidebar.querySelector('.nav-close').onclick=()=>setMenu(false);backdrop.onclick=()=>setMenu(false);
 sidebar.onkeydown=event=>{if(!mobile.matches||!sidebar.classList.contains('open'))return;if(event.key==='Escape'){event.preventDefault();setMenu(false)}if(event.key==='Tab'){const controls=[...sidebar.querySelectorAll('button,a')].filter(el=>!el.disabled&&el.getClientRects().length);const first=controls[0],last=controls.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus()}}};
 window.onresize=()=>{if(!sidebar.isConnected)return;sidebar.inert=mobile.matches&&!sidebar.classList.contains('open');document.querySelector('.main-area').inert=mobile.matches&&sidebar.classList.contains('open')};
 document.querySelectorAll('[data-page]').forEach(button=>button.onclick=()=>{navigateTo(button.dataset.page);document.getElementById('content')?.focus()});
 document.getElementById('logout').onclick=async()=>{if(page==='control'&&controlCenterInstance&&!controlCenterInstance.confirmLeave())return;const button=document.getElementById('logout');button.disabled=true;try{await api('/auth/logout',{method:'POST'});me=null;login()}catch(error){button.disabled=false;button.textContent='Retry sign out';button.title=error.message}};
 attachServices();const focus=ccFocus,feature=featurePages().find(p=>p.id===page);ccFocus=null;
 if(page==='control')controlCenterInstance=window.ControlCenter.mount({api,me,host:document.getElementById('content'),selectedCameraId,onCameraSelected:id=>{selectedCameraId=id},onNavigate:navigateTo,focus});
 else if(feature)featureInstance=feature.mount({api,me,host:document.getElementById('content'),onNavigate:navigateTo,formatTime:dateLabel});
 else ({overview:overviewPage,live:livePage,analysis:analysisPage,incidents:incidentPage,modules:modulesPage,settings:settingsPage}[page]||overviewPage)();
}
async function overviewPage(){stopTimers();const host=document.getElementById('content');host.innerHTML=`${pageHead('System overview','Source health, worker availability and analysis activity.')}<div class="notice">Loading current application state…</div>`;try{const data=await api('/overview');if(!host.isConnected)return;cams=data.cameras;const enabled=cams.filter(c=>c.enabled),fresh=enabled.filter(c=>c.status==='ONLINE'&&!c.preview_stale).length,active=data.active_incidents;host.innerHTML=`${pageHead('System overview','Source health, worker availability and analysis activity.')}<div class="grid three-col"><article class="card"><div class="metric-label">Connected cameras</div><div class="metric">${data.source_counts.online}</div><div class="metric-note">${data.source_counts.offline} offline · ${data.source_counts.disabled} disabled</div></article><article class="card"><div class="metric-label">Fresh previews</div><div class="metric">${fresh} / ${enabled.length}</div><div class="metric-note">Frame freshness is separate from camera and worker state.</div></article><article class="card"><div class="metric-label">Ingestion worker</div><div class="metric">${esc(data.worker)}</div><div class="metric-note">Worker lease heartbeat</div></article><article class="card"><div class="metric-label">Active incidents</div><div class="metric">${active}</div><div class="metric-note">${Object.entries(data.incident_counts).map(([key,value])=>`${esc(key)} ${value}`).join(' · ')}</div></article><article class="card"><div class="metric-label">Analysis jobs</div><div class="metric">${data.jobs.running} running · ${data.jobs.queued} queued</div><div class="metric-note">${data.jobs.completed} completed · ${data.jobs.failed} failed</div></article><article class="card"><div class="metric-label">Runtime-ready modules</div><div class="metric">${data.modules.filter(m=>['READY','RUNNING'].includes(m.status)).length} / ${data.modules.length}</div><div class="metric-note">Readiness requires local validated weights and runtime.</div></article></div><div class="grid two-col"><section><h2>Camera health</h2>${cams.length?`<div class="health-list">${cams.map(c=>`<div class="health-row"><div><strong>${esc(c.name)}</strong><div class="muted small-text">${esc(c.location)} · ${esc(c.source_type)}</div></div><div class="actions-row">${pill(c.enabled?c.status:'DISABLED',c.enabled?stateTone(c.status):'')} ${pill(!c.enabled?'Not monitored':c.preview_stale?'Preview stale':'Preview fresh',!c.enabled?'':c.preview_stale?'warn':'good')}</div></div>`).join('')}</div>`:'<div class="empty">No camera sources configured.</div>'}</section><section><h2>Model readiness</h2>${data.modules.map(m=>`<div class="health-row"><div><strong>${esc(m.module_id)}</strong><div class="muted small-text">${esc(m.package_version||'Package version unavailable')}</div></div>${pill(m.status,stateTone(m.status))}</div>${m.status!=='READY'&&m.status!=='RUNNING'?`<p class="muted small-text">${esc(m.error||m.weights_path||'Runtime not validated')}</p>`:''}`).join('')}<p class="notice warn">Connected camera status does not mean AI monitoring is active. A module must be runtime-ready and assigned.</p></section></div><h2>Recent incidents</h2>${incidentList(data.recent_incidents||[])}`;bindIncidentActions();pageTimer=setTimeout(()=>{if(page==='overview')overviewPage()},8000)}catch(error){host.innerHTML=`${pageHead('Overview','Current application state.')}<p class="error">${esc(error.message)}</p>`}}
async function livePage(){
 const host=document.getElementById('content');
 liveViewerInstance?.dispose();liveViewerInstance=null;
 let workerState='UNKNOWN';
 try{workerState=(await api('/overview')).worker||'UNKNOWN'}catch{}
 if(page!=='live'||host!==document.getElementById('content'))return;
 liveViewerInstance=window.VisorMonitoring.mountLivePage({host,cameras:cams,selectedCameraId,workerState,userId:me.id,me,
  onCameraSelected:id=>{selectedCameraId=id},
  onCameraDetails:id=>{liveViewerInstance?.dispose();liveViewerInstance=null;cameraDetail(id)},
  onOpenControlCenter:()=>{page='control';render()},
  onAddCamera:()=>cameraForm()
 });
 let refreshing=false;
 pageTimer=setInterval(async()=>{
  if(page!=='live'||refreshing||document.hidden)return;
  refreshing=true;
  try{const [nextCameras,overview]=await Promise.all([api('/cameras'),api('/overview')]);if(page!=='live'||!liveViewerInstance)return;cams=nextCameras;liveViewerInstance.update({cameras:cams,workerState:overview.worker||'UNKNOWN'})}
  catch{if(page==='live'&&liveViewerInstance)liveViewerInstance.update({workerState:'UNKNOWN'})}
  finally{refreshing=false}
 },5000);
}
function cameraForm(camera=null){if(me.role!=='ADMIN')return;const editing=!!camera;const options=editing?`<option value="${esc(camera.source_type)}">${esc(camera.source_type)}</option>`:`<option value="synthetic">Synthetic demo</option><option value="rtsp">RTSP / RTSPS</option><option value="file">Local file</option><option value="webcam">Local webcam (worker computer)</option>`;document.body.insertAdjacentHTML('beforeend',`<dialog id="cameraDialog"><div class="card-header"><div><h2>${editing?'Edit':'Add'} camera source</h2><p class="muted">RTSP credentials are encrypted at rest and never returned here. Blank credentials preserve the existing secret.</p></div><button class="ghost small" data-close-dialog>Close</button></div><form id="cameraForm"><div class="field-grid"><label class="field">Camera name<input name="name" required maxlength="120" value="${esc(camera?.name||'')}"></label><label class="field">Location<input name="location" maxlength="160" value="${esc(camera?.location||'')}"></label><label class="field">Source type<select name="source_type" ${editing?'disabled':''}>${options}</select></label><label class="field">Enabled<select name="enabled"><option value="true" ${camera?.enabled!==false?'selected':''}>Enabled</option><option value="false" ${camera?.enabled===false?'selected':''}>Disabled</option></select></label><label class="field connection-field">${camera?.source_type==='rtsp'?'RTSP / RTSPS URL (leave blank to preserve)':'Source path under approved media root'}<input name="connection" type="password" autocomplete="new-password" placeholder="${camera?.source_type==='rtsp'?'Enter to replace stored credentials':'Relative path under VIGILON_MEDIA_DIR'}" ${camera?.source_type==='synthetic'?'disabled':''}></label><label class="field demo-field">Synthetic scenario<select name="scenario"><option>normal</option><option ${camera?.scenario==='obstruction'?'selected':''}>obstruction</option><option ${camera?.scenario==='person_down'?'selected':''}>person_down</option><option ${camera?.scenario==='smoke_fire'?'selected':''}>smoke_fire</option></select></label></div><details><summary>Processing and reconnect limits</summary><div class="field-grid"><label class="field">Processing FPS<input name="processing_fps" type="number" min="1" max="15" value="${camera?.processing_fps||2}"></label><label class="field">Maximum preview size<input name="resize_limit" type="number" min="160" max="3840" value="${camera?.resize_limit||1280}"></label><label class="field">Connection timeout seconds<input name="timeout_seconds" type="number" min="1" max="30" value="${camera?.timeout_seconds||5}"></label><label class="field">Minimum reconnect seconds<input name="reconnect_min_seconds" type="number" min="1" max="30" value="${camera?.reconnect_min_seconds||1}"></label><label class="field">Maximum reconnect seconds<input name="reconnect_max_seconds" type="number" min="2" max="300" value="${camera?.reconnect_max_seconds||30}"></label></div></details>${editing&&camera.source_type==='rtsp'?'<label class="field check-row"><input type="checkbox" name="clear_connection"> Explicitly clear stored connection credentials</label>':''}<p id="cameraMessage" class="error" role="alert"></p><div class="actions-row"><button type="button" id="testConnection" class="secondary">Test connection</button><button type="submit">${editing?'Save camera':'Create camera'}</button></div></form></dialog>`);const dialog=document.getElementById('cameraDialog'),form=document.getElementById('cameraForm');let dirty=false;form.addEventListener('input',()=>{dirty=true});window.VisorUI.dialog(dialog,{dirty:()=>dirty});const type=form.elements.source_type;type.onchange=()=>{form.querySelector('.demo-field').hidden=type.value!=='synthetic';form.querySelector('.connection-field').hidden=type.value==='synthetic';form.elements.connection.disabled=type.value==='synthetic';form.querySelector('.connection-field').firstChild.textContent=type.value==='rtsp'?'RTSP / RTSPS URL':type.value==='webcam'?'Webcam device index (0 = first camera on the worker computer)':'Source path under approved media root';form.elements.connection.type=type.value==='rtsp'?'password':'text';if(type.value==='webcam')form.elements.connection.placeholder=editing?'Leave blank to keep the current index':'0'};type.onchange();function body(){const values=Object.fromEntries(new FormData(form));return {name:values.name,location:values.location||'',source_type:editing?camera.source_type:values.source_type,connection:values.connection||'',clear_connection:form.elements.clear_connection?.checked||false,enabled:values.enabled==='true',scenario:values.scenario||'normal',processing_fps:+values.processing_fps,resize_limit:+values.resize_limit,timeout_seconds:+values.timeout_seconds,reconnect_min_seconds:+values.reconnect_min_seconds,reconnect_max_seconds:+values.reconnect_max_seconds}}document.getElementById('testConnection').onclick=async()=>{const data=body(),messageBox=document.getElementById('cameraMessage');if(data.source_type==='synthetic'){messageBox.textContent='Synthetic sources do not require a connection test.';return}if(!data.connection&&data.source_type!=='webcam'){messageBox.textContent='Enter a source URL or media path before testing. Stored credentials remain unchanged.';return}messageBox.textContent='Testing with a bounded timeout…';const testButton=document.getElementById('testConnection');testButton.disabled=true;try{const result=await api('/cameras/test-connection',{method:'POST',body:JSON.stringify({source_type:data.source_type,connection:data.connection||(data.source_type==='webcam'?'0':''),timeout_seconds:data.timeout_seconds})});messageBox.textContent=result.message;messageBox.className=result.reachable?'success':'error'}catch(error){messageBox.textContent=error.message}finally{testButton.disabled=false}};form.onsubmit=async event=>{event.preventDefault();const submit=form.querySelector('[type=submit]');if(submit.disabled)return;submit.disabled=true;const data=body();try{if(editing)await api(`/cameras/${camera.id}`,{method:'PATCH',body:JSON.stringify(data)});else await api('/cameras',{method:'POST',body:JSON.stringify(data)});dialog.close();dialog.remove();await loadBase();if(page==='live')render();else if(camera)cameraDetail(camera.id)}catch(error){document.getElementById('cameraMessage').textContent=error.message}finally{submit.disabled=false}}}
async function cameraDetail(id){liveViewerInstance?.dispose();liveViewerInstance=null;selectedCameraId=id;stopTimers();const host=document.getElementById('content');try{const [cameraList,catalog,assignment,rules,overview]=await Promise.all([api('/cameras'),api('/ai/modules'),api(`/cameras/${id}/modules`),api(`/cameras/${id}/rules`),api('/overview')]);if(!host.isConnected)return;cams=cameraList;const camera=cams.find(c=>c.id===id);if(!camera)throw Error('Camera not found');const ready=catalog.modules.filter(m=>['READY','RUNNING'].includes(m.status));host.innerHTML=`${pageHead(camera.name,`${camera.location||'No location'} · ${camera.source_type}${camera.simulated?' · SIMULATED':''}`,`<button id="backLive" class="secondary">Back to cameras</button>${me.role==='ADMIN'?'<button id="editCamera" class="secondary">Edit source</button>':''}`)}<div class="grid two-col"><section class="card"><div class="camera-detail-viewer" data-camera-detail-viewer></div><div class="row" style="margin-top:13px">${pill(camera.enabled?camera.status:'DISABLED',camera.enabled?stateTone(camera.status):'')}${pill(camera.preview_stale?'Preview stale':'Preview fresh',camera.preview_stale?'warn':'good')}${pill(overview.worker==='ONLINE'?'Worker online':'Worker offline',stateTone(overview.worker))}</div><p class="muted small-text">Connection status, frame freshness, worker heartbeat, and AI module status are separate signals.</p></section><section class="card"><h2 style="margin-top:0">AI monitoring</h2><p class="muted">Source enabled: <strong>${camera.enabled?'yes':'no'}</strong>. Simulation: <strong>${camera.simulated?'enabled for this synthetic source':'off'}</strong>.</p>${camera.simulated?'<div class="notice warn">Simulated detections apply only to this generated synthetic feed.</div>':''}${['rtsp','webcam'].includes(camera.source_type)&&!camera.simulated?`<p class="eyebrow">Runtime-ready modules</p>${me.role==='ADMIN'?`<div class="field">Select installed and runtime-ready modules${catalog.modules.map(m=>`<label class="check-row"><input type="checkbox" data-module="${esc(m.module_id)}" ${assignment.modules.includes(m.module_id)?'checked':''} ${!ready.includes(m)?'disabled':''}><span>${esc(m.module_id)} · ${esc(m.status)}</span></label><span class="muted small-text">${!ready.includes(m)?esc(m.error||m.weights_path||'Validate this package and install its approved runtime first.'):m.supported_scenarios?.map(s=>esc(s.scenario_id)).join(' · ')}</span>`).join('')}</div><button id="saveModules">Save monitoring selection</button><p id="moduleMessage" class="muted small-text" role="status"></p>`:`<p>${assignment.modules.map(esc).join(', ')||'No AI module assigned.'}</p>`}<p class="muted small-text">The worker applies saved rules from its shared source configuration. Assignment is not confirmation of monitoring until a ready runtime is processing.</p>`:'<div class="notice">Live AI module assignment is supported for configured RTSP/RTSPS cameras and local webcams. Use Video Analysis for recorded files.</div>'}</section></div><h2>Scenario rules and zones</h2><p class="muted">Draw in the visible image area. Saved coordinates are normalized to the image itself; letterboxing is excluded.</p>${rules.length?`<div class="grid">${rules.map(rule=>`<article class="card"><div class="card-header"><div><strong>${esc(rule.event_type.replaceAll('_',' '))}</strong><div class="muted small-text">${rule.enabled?'Enabled':'Disabled'} · min ${rule.min_duration}s · cooldown ${rule.cooldown}s</div></div>${pill(rule.enabled?'Enabled':'Disabled',rule.enabled?'good':'')}</div>${me.role==='ADMIN'?`<button class="secondary small" data-edit-rule="${rule.id}">Configure scenario</button>`:''}</article>`).join('')}</div>`:'<div class="empty">No scenario rules are configured for this source.</div>'}`;liveViewerInstance=window.VisorMonitoring.mountViewer({host:host.querySelector('[data-camera-detail-viewer]'),cameras:[camera],selectedCameraId:id,mode:'single',workerState:overview.worker||'UNKNOWN',compact:true,formatTime:dateLabel,onSelectCamera:selected=>{selectedCameraId=selected}});document.getElementById('backLive').onclick=()=>{page='live';render()};document.getElementById('editCamera')?.addEventListener('click',()=>cameraForm(camera));document.querySelectorAll('[data-edit-rule]').forEach(button=>button.onclick=()=>ruleEditor(id,+button.dataset.editRule));document.getElementById('saveModules')?.addEventListener('click',async()=>{const selected=[...document.querySelectorAll('[data-module]:checked')].map(input=>input.dataset.module),msg=document.getElementById('moduleMessage');try{const response=await api(`/cameras/${id}/modules`,{method:'PUT',body:JSON.stringify({modules:selected})});msg.textContent=`${response.status}. Configuration saved. Worker application follows its control loop.`;await cameraDetail(id)}catch(error){msg.textContent=error.message}});pageTimer=setInterval(()=>{if(page==='live'&&!document.querySelector('dialog[open],input:focus,select:focus,textarea:focus,[data-module]:checked'))api('/cameras').then(list=>{cams=list;cameraDetail(id)}).catch(()=>{})},7000)}catch(error){host.innerHTML=`${pageHead('Camera details','Source and monitoring status.')}<p class="error">${esc(error.message)}</p>`}}
async function ruleEditor(cameraId,ruleId){try{const [allRules,cameraList]=await Promise.all([api(`/cameras/${cameraId}/rules`),api('/cameras')]);const rule=allRules.find(row=>row.id===ruleId),camera=cameraList.find(row=>row.id===cameraId);if(!rule||!camera)throw Error('Scenario rule not found');const originalPoints=rule.zone?.points||[],dialogMarkup=`<dialog id="ruleDialog"><div class="card-header"><div><h2>Configure ${esc(rule.event_type.replaceAll('_',' '))}</h2><p class="muted">Coordinates are normalized against the displayed frame, excluding letterbox bars.</p></div><button class="ghost small" data-close>Close</button></div><div class="zone-stage"><img id="zoneImage" src="/api/cameras/${cameraId}/preview" alt="Frame used for scenario geometry"><canvas id="zoneCanvas" aria-label="Draw normalized zone or line"></canvas></div><div class="field-grid"><label class="field">Geometry tool<select id="geometryTool"><option value="polygon">Polygon zone · click vertices, double-click finish</option><option value="rectangle" ${rule.zone?.type==='rectangle'?'selected':''}>Rectangle zone · click two corners</option></select></label><label class="field">Minimum duration seconds<input id="minimum" type="number" min="1" max="3600" value="${rule.min_duration}"></label><label class="field">Cooldown seconds<input id="cooldown" type="number" min="0" max="86400" value="${rule.cooldown}"></label><label class="field">Timezone (display/config only)<input id="ruleTimezone" value="${esc(rule.timezone||timezone)}"></label><label class="field">Crossing line (optional)<select id="lineTool"><option value="">No crossing line</option><option value="draw">Draw line on frame</option></select></label><label class="field">Crossing direction<select id="direction"><option value="A_TO_B" ${rule.direction==='A_TO_B'?'selected':''}>A to B</option><option value="B_TO_A" ${rule.direction==='B_TO_A'?'selected':''}>B to A</option></select></label></div><p class="muted small-text">Monitoring schedules are not evaluated. The saved timezone does not schedule or disable monitoring.</p><div class="row"><button id="undoGeometry" class="secondary">Undo point</button><button id="clearGeometry" class="secondary">Clear zone</button><button id="clearLine" class="secondary">Clear line</button><label class="check-row"><input id="ruleEnabled" type="checkbox" ${rule.enabled?'checked':''}> Scenario enabled</label></div><details><summary>Enter zone and line coordinates with the keyboard</summary><label class="field">Normalized geometry JSON<textarea id="keyboardGeometry" rows="5">${esc(JSON.stringify({points:originalPoints,line:rule.line||[]},null,2))}</textarea></label><p class="muted small-text">Use points for the zone and an optional line of two points. Each [x, y] coordinate is between 0 and 1.</p><button type="button" class="secondary" id="applyKeyboardGeometry">Apply coordinates</button></details><p id="ruleMessage" class="error" role="alert"></p><button id="saveGeometry">Save scenario</button></dialog>`;document.body.insertAdjacentHTML('beforeend',dialogMarkup);const dialog=document.getElementById('ruleDialog'),canvas=document.getElementById('zoneCanvas'),image=document.getElementById('zoneImage'),ctx=canvas.getContext('2d');let points=originalPoints.map(point=>[...point]),line=(rule.line||[]).map(point=>[...point]),start=null,drawingLine=false;let ruleDirty=false;dialog.addEventListener('input',()=>{ruleDirty=true});window.VisorUI.dialog(dialog,{dirty:()=>ruleDirty,cleanup:()=>geometryObserver.disconnect()});const imageArea=()=>{const rect=canvas.getBoundingClientRect(),scale=Math.min(rect.width/image.naturalWidth,rect.height/image.naturalHeight),width=image.naturalWidth*scale,height=image.naturalHeight*scale;return{left:(rect.width-width)/2,top:(rect.height-height)/2,width,height}};const normalized=(point,area)=>[area.left+point[0]*area.width,area.top+point[1]*area.height];function draw(){const rect=canvas.getBoundingClientRect(),ratio=devicePixelRatio||1;canvas.width=rect.width*ratio;canvas.height=rect.height*ratio;ctx.setTransform(ratio,0,0,ratio,0,0);ctx.clearRect(0,0,rect.width,rect.height);if(!image.naturalWidth)return;const area=imageArea();if(points.length){ctx.beginPath();points.forEach((point,index)=>{const [x,y]=normalized(point,area);index?ctx.lineTo(x,y):ctx.moveTo(x,y)});if(points.length>2)ctx.closePath();ctx.fillStyle='rgba(98,198,193,.16)';ctx.strokeStyle='#62c6c1';ctx.lineWidth=2;ctx.fill();ctx.stroke()}for(const point of points){const[x,y]=normalized(point,area);ctx.fillStyle='#e7c579';ctx.beginPath();ctx.arc(x,y,4,0,Math.PI*2);ctx.fill()}if(line.length===2){const a=normalized(line[0],area),b=normalized(line[1],area);ctx.strokeStyle='#f2bc65';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(...a);ctx.lineTo(...b);ctx.stroke();const angle=Math.atan2(b[1]-a[1],b[0]-a[0]);ctx.beginPath();ctx.moveTo(b[0],b[1]);ctx.lineTo(b[0]-12*Math.cos(angle-.5),b[1]-12*Math.sin(angle-.5));ctx.lineTo(b[0]-12*Math.cos(angle+.5),b[1]-12*Math.sin(angle+.5));ctx.closePath();ctx.fillStyle='#f2bc65';ctx.fill()}}function pointFrom(event){const rect=canvas.getBoundingClientRect(),area=imageArea(),x=event.clientX-rect.left-area.left,y=event.clientY-rect.top-area.top;if(x<0||y<0||x>area.width||y>area.height)return null;return[x/area.width,y/area.height]}image.onload=draw;const geometryObserver=new ResizeObserver(draw);geometryObserver.observe(canvas);canvas.onclick=event=>{ruleDirty=true;const point=pointFrom(event);if(!point)return;if(drawingLine){line=line.length<1?[point]:[line[0],point];drawingLine=line.length<2}else if(document.getElementById('geometryTool').value==='rectangle'){if(!start){start=point;points=[point]}else{points=[[start[0],start[1]],[point[0],start[1]],[point[0],point[1]],[start[0],point[1]]];start=null}}else points.push(point);draw()};canvas.ondblclick=event=>{if(!drawingLine&&points.length>1)points.pop();draw()};document.getElementById('lineTool').onchange=event=>{if(event.target.value==='draw'){drawingLine=true;line=[]}};document.getElementById('undoGeometry').onclick=()=>{ruleDirty=true;points.pop();start=null;draw()};document.getElementById('clearGeometry').onclick=()=>{ruleDirty=true;points=[];start=null;draw()};document.getElementById('clearLine').onclick=()=>{ruleDirty=true;line=[];drawingLine=false;document.getElementById('lineTool').value='';draw()};document.getElementById('applyKeyboardGeometry').onclick=()=>{try{const geometry=window.VisorUI.parseGeometry(document.getElementById('keyboardGeometry').value);points=geometry.points;line=geometry.line;ruleDirty=true;document.getElementById('geometryTool').value='polygon';document.getElementById('ruleMessage').textContent='';draw()}catch(error){document.getElementById('ruleMessage').textContent=error.message}};document.getElementById('saveGeometry').onclick=async event=>{const save=event.currentTarget;if(save.disabled)return;save.disabled=true;try{const result=await api(`/rules/${ruleId}`,{method:'PUT',body:JSON.stringify({event_type:rule.event_type,enabled:document.getElementById('ruleEnabled').checked,min_duration:+document.getElementById('minimum').value,cooldown:+document.getElementById('cooldown').value,zone:{type:document.getElementById('geometryTool').value==='rectangle'?'rectangle':'polygon',points},timezone:document.getElementById('ruleTimezone').value,line:line.length===2?line:null,direction:document.getElementById('direction').value})});dialog.close();dialog.remove();await cameraDetail(cameraId);return result}catch(error){document.getElementById('ruleMessage').textContent=error.message}finally{save.disabled=false}}}catch(error){alert(error.message)}}
function analysisPage(){
 const host=document.getElementById('content');
 host.innerHTML=`${pageHead('Video Analysis','Import authorized recordings and inspect persistent analysis jobs.',me.role==='ADMIN'?'<button id="chooseVideo">Import video</button>':'')}<ol class="workflow-steps" aria-label="Analysis workflow"><li><b>1</b> Import video</li><li><b>2</b> Choose modules &amp; rules</li><li><b>3</b> Review results</li></ol><input id="videoFile" type="file" accept="video/mp4,video/quicktime,video/x-matroska,video/x-msvideo,video/webm,.mp4,.mov,.mkv,.avi,.webm,.m4v" hidden><div id="importPanel"></div><section id="analysisConfig"></section>${me.role==='ADMIN'?'<details class="demo-disclosure"><summary>Try a generated demo · SIMULATED</summary><p class="muted">Creates a short synthetic video and simulated event through the same persistent FILE worker. It never analyzes uploaded recordings or uses model weights.</p><label class="field">Scenario<select id="simulatedScenario"><option value="obstruction">Obstruction</option><option value="person_down">Person down</option><option value="smoke_fire">Smoke / fire</option></select></label><button id="runSimulatedDemo" class="secondary">Run generated SIMULATED demo</button><p id="simulatedMessage" role="status"></p></details>':''}<h2>Analysis jobs</h2><div class="row" style="margin:15px 0"><label class="field" style="min-width:170px">Job status<select id="jobFilter"><option>All</option><option>QUEUED</option><option>RUNNING</option><option>CANCELLED</option><option>COMPLETED</option><option>FAILED</option></select></label><button class="secondary" id="refreshJobs">Refresh jobs</button></div><div id="jobList"></div><section id="jobResults"></section>`;
 document.getElementById('chooseVideo')?.addEventListener('click',()=>document.getElementById('videoFile').click());
 document.getElementById('runSimulatedDemo')?.addEventListener('click',async event=>{const button=event.currentTarget,message=document.getElementById('simulatedMessage');button.disabled=true;message.textContent='Generating a synthetic clip and queueing it for the FILE worker…';try{const job=await api('/ai/demo-jobs',{method:'POST',body:JSON.stringify({scenario:document.getElementById('simulatedScenario').value})});message.textContent=`${job.input_name} queued. Output is explicitly simulated.`;await loadJobs()}catch(error){message.textContent=error.message}finally{button.disabled=false}});
 document.getElementById('videoFile').onchange=async event=>{const file=event.target.files?.[0];if(!file)return;const panel=document.getElementById('importPanel');if(file.size>512*1024*1024){panel.innerHTML='<p class="error">The upload limit is 512 MiB.</p>';return}document.getElementById('chooseVideo').disabled=true;panel.innerHTML=`<div class="notice">Uploading and validating ${esc(file.name)}…</div>`;try{const response=await fetch('/api/ai/imports',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/octet-stream','X-File-Name':encodeURIComponent(file.name)},body:file});let body={};try{body=await response.json()}catch{}if(!response.ok)throw Error(message(body.detail)||`Upload failed (${response.status})`);if(panel.isConnected)showImported(body)}catch(error){panel.innerHTML=`<div class="notice bad">${esc(error.message)}</div>`}finally{const button=document.getElementById('chooseVideo');if(button)button.disabled=false}};
 document.getElementById('jobFilter').onchange=event=>{jobFilter=event.target.value;loadJobs()};document.getElementById('refreshJobs').onclick=loadJobs;loadJobs();pageTimer=setInterval(()=>{if(!document.hidden)loadJobs()},2500);
}
function showImported(file){
 const panel=document.getElementById('importPanel');
 panel.innerHTML=`<article class="card"><div class="card-header"><div><h3>${esc(file.name)}</h3><p class="muted small-text">${(file.bytes/1048576).toFixed(1)} MiB · ${file.duration_seconds?`${file.duration_seconds.toFixed(2)} s · `:''}${file.width}×${file.height} · Browser playback ${file.browser_playback_mime?'may be supported':'depends on codec'}</p></div><div class="actions-row">${pill('Imported','good')}<button id="removeImport" class="danger small">Remove import</button></div></div><video class="preview-player" controls preload="metadata" src="/api/ai/imports/${encodeURIComponent(file.import_id)}/media"></video></article>`;
 panel.querySelector('video').onerror=()=>{const note=document.createElement('p');note.className='notice warn';note.textContent='Browser playback is unsupported for this codec. OpenCV decoded the video; playback and decoding are separate.';panel.append(note)};
 document.getElementById('removeImport').onclick=async event=>{event.currentTarget.disabled=true;try{await api(`/ai/imports/${encodeURIComponent(file.import_id)}`,{method:'DELETE'});panel.innerHTML='<div class="notice">Imported media removed.</div>';document.getElementById('analysisConfig').innerHTML=''}catch(error){event.currentTarget.disabled=false;const note=document.createElement('p');note.className='error';note.textContent=error.message;panel.append(note)}};
 analysisConfig(file)
}
async function loadJobs(){const host=document.getElementById('jobList');if(!host)return;try{const jobs=await api('/ai/jobs'),shown=jobs.filter(job=>jobFilter==='All'||job.status===jobFilter);host.innerHTML=shown.length?shown.map(job=>{const status=job.cancel_requested&&job.status==='RUNNING'?'CANCELLING':job.status,percent=job.total_frames?Math.min(100,job.progress_frames/job.total_frames*100):null;return `<article class="card" style="margin:9px 0"><div class="card-header"><div><strong>${esc(job.input_name)}</strong><div class="muted small-text">${(job.modules||[]).map(esc).join(' · ')} · started ${esc(dateLabel(job.started_at||job.created_at))}</div></div>${pill(status,stateTone(status))}</div><p class="muted small-text">${job.progress_frames} / ${job.total_frames??'unknown'} frames · ${job.events} events · ${job.total_frames?`${percent.toFixed(1)}% frames processed`:'processing position unavailable'} · completed ${esc(dateLabel(job.completed_at))}</p><div class="progress-track"><span style="width:${job.status==='COMPLETED'?100:percent||0}%"></span></div>${job.error?`<div class="notice bad" style="margin-top:9px">${esc(job.error)}</div>`:''}<div class="actions-row" style="margin-top:10px"><button class="secondary small" data-view-job="${esc(job.job_id)}">Inspect results</button>${me.role==='ADMIN'&&['QUEUED','RUNNING'].includes(job.status)?`<button class="danger small" data-cancel-job="${esc(job.job_id)}">${job.cancel_requested?'Cancellation pending':'Cancel job'}</button>`:''}${me.role==='ADMIN'&&!['QUEUED','RUNNING'].includes(job.status)?`<button class="ghost small" data-delete-job="${esc(job.job_id)}">Delete job results</button>`:''}</div></article>`}).join(''):'<div class="empty">No jobs in this state. Jobs and results persist when you refresh this page.</div>';host.querySelectorAll('[data-view-job]').forEach(button=>button.onclick=()=>showJobResults(button.dataset.viewJob));host.querySelectorAll('[data-cancel-job]').forEach(button=>button.onclick=async()=>{button.disabled=true;try{await api(`/ai/jobs/${button.dataset.cancelJob}/cancel`,{method:'POST',body:'{}'});await loadJobs()}catch(error){alert(error.message)}finally{button.disabled=false}});host.querySelectorAll('[data-delete-job]').forEach(button=>button.onclick=async()=>{button.disabled=true;try{await api(`/ai/jobs/${button.dataset.deleteJob}`,{method:'DELETE'});if(selectedJob===button.dataset.deleteJob){selectedJob=null;loadedResult=null;document.getElementById('jobResults').innerHTML=''}await loadJobs()}catch(error){alert(error.message)}finally{button.disabled=false}});if(selectedJob&&loadedResult===null&&document.getElementById('jobResults')&&!document.getElementById('jobResults').innerHTML)await showJobResults(selectedJob)}catch(error){host.innerHTML=`<p class="error">${esc(error.message)}</p>`}}
async function showJobResults(id){selectedJob=id;const host=document.getElementById('jobResults');host.innerHTML='<div class="notice">Loading analysis result…</div>';try{const result=await api(`/ai/jobs/${encodeURIComponent(id)}/results`);loadedResult=result;const job=await api(`/ai/jobs/${encodeURIComponent(id)}`),events=result.events||[],maxTime=Math.max(1,...events.map(event=>Number(event.media_time)||0));const modules=[...new Set(events.map(event=>event.detection?.module_id||event.scenario_id).filter(Boolean))],types=[...new Set(events.map(event=>event.event_type).filter(Boolean))];host.innerHTML=`<h2>Analysis results · ${esc(result.status)}</h2><div class="notice ${result.status==='FAILED'?'bad':''}">${result.status==='COMPLETED'&&events.length===0?'Analysis completed with no confirmed events in the processed frames.':result.status==='FAILED'?'Analysis failed; results may be partial.':result.status==='CANCELLED'?'Analysis was cancelled; results are partial.':`Processed ${result.frames||0} frames. ${events.length} events in the result.`} ${result.events_truncated?'Event list capped at 10,000 results.':''}</div><div class="grid two-col"><section><video id="analysisPlayer" class="preview-player" controls preload="metadata" src="/api/ai/jobs/${encodeURIComponent(id)}/media"></video><p id="codecNote" class="muted small-text">Browser codec playback is independent from OpenCV decoding and analysis.</p><div class="timeline" id="eventTimeline" aria-label="Analysis event timeline">${events.map(event=>`<button class="timeline-marker" style="left:${Math.min(100,(Number(event.media_time)||0)/maxTime*100)}%" data-seek-event="${Number(event.media_time)||0}" title="${esc(event.event_type)} at ${(Number(event.media_time)||0).toFixed(2)} seconds" aria-label="Seek to ${esc(event.event_type)}"></button>`).join('')}</div><div class="row"><label class="field">Event type<select id="eventTypeFilter"><option value="">All types</option>${types.map(type=>`<option>${esc(type)}</option>`).join('')}</select></label><label class="field">Module/scenario<select id="eventModuleFilter"><option value="">All modules</option>${modules.map(module=>`<option>${esc(module)}</option>`).join('')}</select></label></div></section><section><div class="card-header"><div><h3>Event timeline</h3><p class="muted small-text">Times are relative to the recording media clock.</p></div><div class="actions-row"><button id="downloadJson" class="secondary small">Download JSON</button><button id="downloadCsv" class="secondary small">Download CSV</button></div></div><div class="event-list" id="eventList"></div></section></div>`;const player=document.getElementById('analysisPlayer');player.onerror=()=>{document.getElementById('codecNote').textContent='This browser cannot play the uploaded codec. Events and media timestamps remain available; use a compatible local player.'};host.querySelectorAll('[data-seek-event]').forEach(button=>button.onclick=()=>seekMedia(Number(button.dataset.seekEvent)));document.getElementById('eventTypeFilter').onchange=renderEvents;document.getElementById('eventModuleFilter').onchange=renderEvents;document.getElementById('downloadJson').onclick=()=>download(`${job.input_name||'analysis'}-results.json`,JSON.stringify(result,null,2),'application/json');document.getElementById('downloadCsv').onclick=()=>download(`${job.input_name||'analysis'}-events.csv`,eventsCsv(events),'text/csv');renderEvents();function renderEvents(){const type=document.getElementById('eventTypeFilter').value,module=document.getElementById('eventModuleFilter').value,filtered=events.filter(event=>(!type||event.event_type===type)&&(!module||(event.detection?.module_id||event.scenario_id)===module));document.getElementById('eventList').innerHTML=filtered.length?filtered.map((event,index)=>`<button class="event-button" data-event-index="${events.indexOf(event)}"><strong>${Number(event.media_time||0).toFixed(2)}s · ${esc(event.event_type)}</strong><div class="muted small-text">${esc(event.detection?.module_id||event.scenario_id)} · ${esc(event.detection?.label||'')} · frame ${esc(event.frame_id)}</div></button>`).join(''):'<div class="empty">No events match these filters.</div>';document.querySelectorAll('[data-event-index]').forEach(button=>button.onclick=()=>seekMedia(Number(events[+button.dataset.eventIndex].media_time)||0))}function seekMedia(position){player.currentTime=position;player.play().catch(()=>{})}}catch(error){host.innerHTML=`<div class="notice warn">${esc(error.message)}${error.message.includes('not available yet')?' The worker has not published the result file yet.':''}</div>`;loadedResult=null}}
function download(name,content,type){const url=URL.createObjectURL(new Blob([content],{type})),anchor=document.createElement('a');anchor.href=url;anchor.download=name.replace(/[\\/:*?"<>|]/g,'_');anchor.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function eventsCsv(events){const columns=['media_time','event_type','scenario_id','module_id','label','score','track_id','frame_id','simulated'];const quote=value=>`"${String(value??'').replaceAll('"','""')}"`;return [columns.join(','),...events.map(event=>[event.media_time,event.event_type,event.scenario_id,event.detection?.module_id,event.detection?.label,event.detection?.score,event.detection?.track_id,event.frame_id,event.simulated].map(quote).join(','))].join('\r\n')}
async function modulesPage(){const host=document.getElementById('content');host.innerHTML=`${pageHead('AI Modules','Built-in packages, validation status, and worker reload outcomes.')}<p class="muted">Only validated, runtime-ready modules can be assigned to cameras or recordings.</p><div id="moduleCatalog" class="grid module-catalog"></div>`;await loadModuleCatalog();pageTimer=setInterval(()=>{if(!document.hidden&&!host.querySelector('details[open],button:disabled,button:focus'))loadModuleCatalog()},3500)}
async function loadModuleCatalog(){const host=document.getElementById('moduleCatalog');if(!host)return;try{const catalog=await api('/ai/modules');if(!host.isConnected)return;host.innerHTML=catalog.modules.map(module=>`<article class="card"><div class="card-header"><div><h3>${esc(module.module_id==='people_vehicle'?'People & vehicles':module.module_id==='fire_smoke'?'Fire & smoke':module.module_id)}</h3><p class="muted small-text">Package ${esc(module.package_version||'unavailable')}</p></div>${pill(module.status,stateTone(module.status))}</div><p>${esc(module.error||'Runtime status reported by the worker.')}</p><details><summary>Package details &amp; validation history</summary><div class="muted small-text">Adapter ${esc(module.adapter_id||'—')} · processed ${module.processed||0} · inference ${module.latency_ms||0} ms</div><p class="muted small-text">Weights: <code>${esc(module.weights_path||'Package path unavailable')}</code></p><p class="muted small-text">Scenarios: ${(module.supported_scenarios||[]).map(item=>`${esc(item.scenario_id)} (${esc(item.event_type)})`).join(' · ')||'Unavailable until package metadata validates'}</p><p class="muted small-text">Last validation: ${esc(module.last_validation?.status||'not run')}${module.last_validation?.completed_at?' · '+esc(dateLabel(module.last_validation.completed_at)):''}${module.last_validation?.error?' · '+esc(module.last_validation.error):''} · Last reload: ${esc(module.last_reload?.status||'not requested')}${module.last_reload?.completed_at?' · '+esc(dateLabel(module.last_reload.completed_at)):''}${module.last_reload?.error?' · '+esc(module.last_reload.error):''}</p></details>${me.role==='ADMIN'?`<div class="actions-row"><button class="secondary small" data-validate="${esc(module.module_id)}" data-mode="metadata">Validate package</button><button class="secondary small" data-validate="${esc(module.module_id)}" data-mode="runtime">Validate runtime</button><button class="secondary small" data-reload="${esc(module.module_id)}">Queue worker reload</button></div><p class="muted small-text" id="moduleOutcome-${esc(module.module_id)}"></p>`:''}</article>`).join('');host.querySelectorAll('[data-validate]').forEach(button=>button.onclick=async()=>{button.disabled=true;const out=document.getElementById(`moduleOutcome-${button.dataset.validate}`);try{const result=await api(`/admin/ai/modules/${button.dataset.validate}/validate`,{method:'POST',body:JSON.stringify({mode:button.dataset.mode})});out.textContent=`${button.dataset.mode} validation: ${result.status} · ${result.error||'passed'}`;await loadModuleCatalog()}catch(error){out.textContent=error.message}finally{button.disabled=false}});host.querySelectorAll('[data-reload]').forEach(button=>button.onclick=async()=>{button.disabled=true;const out=document.getElementById(`moduleOutcome-${button.dataset.reload}`);try{const result=await api(`/admin/ai/modules/${button.dataset.reload}/reload`,{method:'POST',body:'{}'});out.textContent=`Reload ${result.status}; waiting for worker result…`;const moduleId=button.dataset.reload;let finished=false;for(let attempt=0;attempt<12&&!finished;attempt++){await new Promise(resolve=>setTimeout(resolve,1000));const current=await api('/ai/modules'),state=current.modules.find(item=>item.module_id===moduleId);if(state?.last_reload?.requested_at===result.requested_at&&state.last_reload.completed_at){out.textContent=`Worker result ${state.last_reload.status}: ${state.last_reload.error||'runtime loaded'}`;finished=true}}if(!finished)out.textContent='Reload is still queued. Worker has not published a result yet.';await loadModuleCatalog()}catch(error){out.textContent=error.message}finally{button.disabled=false}})}catch(error){host.innerHTML=`<p class="error">${esc(error.message)}</p>`}}
function incidentList(items){return items.length?`<div class="incident-table"><div class="incident-table-row incident-table-head" aria-hidden="true"><span>Event</span><span>Camera / location</span><span>Severity</span><span>Status</span><span>First observed</span></div>${items.map(i=>`<button class="incident-table-row" data-incident-detail="${i.id}" aria-label="Review incident ${i.id}: ${esc(i.event_type.replaceAll('_',' '))}"><span><strong>${esc(i.event_type.replaceAll('_',' '))}</strong><small class="muted">#${i.id}${i.simulated?' · SIMULATED':''}</small></span><span>${esc(i.camera)}<small class="muted" style="display:block">${esc(i.location)}</small></span><span><span class="cc-severity ${esc(i.severity.toLowerCase())}">${esc(i.severity)}</span></span><span>${pill(i.status.replaceAll('_',' '),i.status==='NEW'?'warn':i.status==='ACKNOWLEDGED'?'':'good')}</span><span class="muted small-text">${esc(dateLabel(i.first_seen))}</span></button>`).join('')}</div>`:'<div class="empty"><h3>No incidents to review</h3><p>Try changing the filters. Historical video analysis results are kept in Video Analysis.</p></div>'}
function incidentPage(){const host=document.getElementById('content');host.innerHTML=`${pageHead('Incidents','Review evidence, record decisions and follow each incident to resolution.')}<div class="filterbar"><label class="field">Search<input id="incidentSearch" placeholder="Camera, location, or event"></label><label class="field">Status<select id="incidentStatus"><option value="">All</option>${['NEW','ACKNOWLEDGED','RESOLVED','FALSE_ALARM'].map(value=>`<option>${value}</option>`).join('')}</select></label><label class="field">Source mode<select id="incidentMode"><option value="">All</option><option>LIVE</option><option>SIMULATED</option></select></label><label class="field">Severity<select id="incidentSeverity"><option value="">All</option>${['LOW','MEDIUM','HIGH','CRITICAL'].map(value=>`<option>${value}</option>`).join('')}</select></label><button id="filterIncidents">Apply filters</button><button id="resetIncidents" class="secondary">Reset</button></div><div id="incidentRows" class="grid" style="margin-top:15px">${incidentList(allIncidents)}</div><div class="row"><button id="olderIncidents" class="secondary">Load older</button><span id="incidentPageNote" class="muted small-text"></span></div><div id="incidentDetails"></div>`;const filters=()=>{const q=new URLSearchParams();for(const [id,key] of [['incidentSearch','search'],['incidentStatus','status'],['incidentMode','source_mode'],['incidentSeverity','severity']]){const value=document.getElementById(id).value;if(value)q.set(key,value)}return q};document.getElementById('filterIncidents').onclick=async()=>{try{const q=filters();q.set('limit','100');allIncidents=await api('/incidents?'+q);document.getElementById('incidentRows').innerHTML=incidentList(allIncidents);bindIncidentActions();document.getElementById('incidentPageNote').textContent='Showing up to 100 results.'}catch(error){document.getElementById('incidentPageNote').textContent=error.message}};document.getElementById('resetIncidents').onclick=async()=>{allIncidents=await api('/incidents?limit=100');incidentPage()};document.getElementById('olderIncidents').onclick=async()=>{const q=filters();q.set('limit','100');q.set('offset',String(allIncidents.length));try{const next=await api('/incidents?'+q);allIncidents=[...allIncidents,...next];document.getElementById('incidentRows').innerHTML=incidentList(allIncidents);bindIncidentActions();document.getElementById('incidentPageNote').textContent=`Showing ${allIncidents.length} incidents.`}catch(error){document.getElementById('incidentPageNote').textContent=error.message}};bindIncidentActions()}
function bindIncidentActions(){document.querySelectorAll('[data-incident-detail]').forEach(button=>button.onclick=()=>showIncidentDetail(+button.dataset.incidentDetail))}
async function showIncidentDetail(id){
 const trigger=document.activeElement;
 try{const incident=await api(`/incidents/${id}`);document.querySelector('#incidentReview')?.close();
 const dialog=document.createElement('dialog');dialog.id='incidentReview';dialog.style.width='1060px';
 dialog.innerHTML=`<div class="card-header"><div><div class="eyebrow">Incident #${id}${incident.simulated?' · SIMULATED':''}</div><h2>${esc(incident.event_type.replaceAll('_',' '))}</h2><p class="muted">${esc(incident.camera)} · ${esc(incident.location)}</p></div><button class="ghost small" data-close>Close</button></div><div class="incident-review-layout"><div><h3>Incident-time evidence</h3>${window.VisorIncidents.renderEvidence(incident,esc)}<p class="muted small-text">Captured at the event. Live video is available in Control Center.</p><button class="secondary" data-open-incident>Open in Control Center</button></div><div>${pill(incident.status.replaceAll('_',' '))} <span class="cc-severity ${esc(incident.severity.toLowerCase())}">${esc(incident.severity)}</span><p class="muted small-text" style="margin-top:12px">First observed ${esc(dateLabel(incident.first_seen))}<br>Last observed ${esc(dateLabel(incident.last_seen))}</p>${['NEW','ACKNOWLEDGED'].includes(incident.status)?`<form id="incidentActionForm"><label class="field">Operator note <textarea name="note" maxlength="500" placeholder="Add context for the next operator"></textarea></label><div class="actions-row">${incident.status==='NEW'?'<button name="status" value="ACKNOWLEDGED">Acknowledge</button>':''}<button name="status" value="RESOLVED" class="secondary">Resolve</button><button name="status" value="FALSE_ALARM" class="danger">False alarm</button></div><p class="muted small-text">Acknowledging starts review. Resolution records your decision; it does not prove the scene cleared.</p><p class="error" role="alert" data-action-error></p></form>`:'<p class="notice">Review complete. The incident and its history are retained.</p>'}<h3>Operator history</h3><div class="audit">${incident.history?.length?incident.history.map(h=>`<div class="audit-item"><strong>${esc(h.actor)}</strong> · ${esc(h.from)} → ${esc(h.to)}<div>${esc(h.note||'No note')}</div><small>${esc(dateLabel(h.at))}</small></div>`).join(''):'<p class="muted">No actions recorded yet.</p>'}</div><details><summary>Recorded event details</summary><p class="small-text">${esc(JSON.stringify(incident.metadata||{}))}</p></details></div></div>`;
 document.body.append(dialog);window.VisorUI.dialog(dialog,{dirty:()=>!!dialog.querySelector('textarea')?.value,cleanup:()=>trigger?.isConnected&&trigger.focus()});
 dialog.querySelector('[data-open-incident]').onclick=()=>{if(dialog.querySelector('textarea')?.value&&!confirm('Discard the unsaved note and open Control Center?'))return;dialog.close();navigateTo('control',{focus:{incidentId:id}})};
 const form=dialog.querySelector('form');if(form)form.onsubmit=async event=>{event.preventDefault();if(form.dataset.pending)return;form.dataset.pending='true';const status=event.submitter?.value||'ACKNOWLEDGED',note=form.elements.note.value;form.querySelectorAll('button').forEach(b=>b.disabled=true);try{await api(`/incidents/${id}/action`,{method:'POST',body:JSON.stringify({status,note})});dialog.close();await loadBase();if(page==='incidents')incidentPage();await showIncidentDetail(id)}catch(error){dialog.querySelector('[data-action-error]').textContent=error.message}finally{delete form.dataset.pending;form.querySelectorAll('button').forEach(b=>b.disabled=false)}};
 }catch(error){const out=document.createElement('p');out.className='error';out.role='alert';out.textContent=error.message;document.getElementById('content')?.prepend(out)}
}
function settingsPage(){const host=document.getElementById('content');host.innerHTML=`${pageHead('Settings','Operational defaults and currently supported configuration.')}<div class="grid two-col"><section class="card"><h2 style="margin-top:0">Regional display</h2><div class="field">Application display timezone<input value="${esc(timezone)}" disabled></div><p class="muted small-text">Timestamps are stored as UTC and displayed in the configured timezone. User-specific preferences are not implemented.</p></section><section class="card"><h2 style="margin-top:0">Worker and media operation</h2><p>Camera streams are opened by the ingestion worker, not by browser tiles.</p><p>Video imports allow 512 MiB per file, supported extensions, and decoded-frame validation.</p><p class="muted small-text">Imports: 100 files / 5 GiB configured limit. Job queue: 20 queued/running jobs.</p></section><section class="card"><h2 style="margin-top:0">Monitoring schedules</h2><p class="muted">Monitoring runs continuously for enabled sources. Scheduled monitoring is not available.</p></section><section class="card"><h2 style="margin-top:0">Evidence and privacy</h2><p>Preview, imported media, and evidence routes require authentication. Source secrets are never returned to this interface.</p><p class="muted small-text">Evidence retention runs only when an administrator invokes the existing retention command.</p></section></div>`}
init();
